// Problem RFC 9457 problem details. `type` is a stable URI per error kind.
type Problem struct {
	// Code Stable machine-readable error code (also the suffix of `type`); doubles as the i18n key base.
	//
	// Example: not_found
	Code string `json:"code"`

	// Detail Explanation specific to this occurrence. Never contains internals or SQL.
	//
	// Example: No such resource.
	Detail *string `json:"detail,omitempty"`

	// Errors Field-level validation errors.
	Errors *[]struct {
		// Code Stable machine-readable code for this field error.
		//
		// Example: required
		Code string `json:"code"`

		// Field Name or path of the offending field.
		//
		// Example: name
		Field string `json:"field"`

		// Message Optional human-readable explanation.
		//
		// Example: must not be empty
		Message *string `json:"message,omitempty"`
	} `json:"errors,omitempty"`

	// Instance URI reference identifying this occurrence.
	//
	// Example: /v1/resources/0190a1b2-c3d4-7e5f-8a9b-0c1d2e3f4a5b
	Instance *string `json:"instance,omitempty"`

	// Reason Optional sub-code that refines `code`, for example approval_not_executable carries not_approved, lapsed, executed, not_approver or subject_changed.
	//
	// Example: not_approved
	Reason *string `json:"reason,omitempty"`

	// RequestId Request ID for log correlation.
	//
	// Example: req_0190a1b2c3d4
	RequestId *string `json:"request_id,omitempty"`

	// Status HTTP status code.
	//
	// Example: 404
	Status int `json:"status"`

	// Title Short human-readable summary; not for programmatic use.
	//
	// Example: Resource not found
	Title string `json:"title"`

	// Type Stable URI identifying the error kind, urn:hostry:problem:<code>.
	//
	// Example: urn:hostry:problem:not_found
	Type string `json:"type"`
}

